sp=importlib.util.spec_from_file_location('p10','/home/claude/kl/b3/p10.py'); p10=importlib.util.module_from_spec(sp); sp.loader.exec_module(p10)
HEAD,body,tail,D=p10.HEAD,p10.body,p10.tail,p10.D
IDLE_END="The swaying of the hips, shoulders and torso is large enough to be clearly seen from far away and never stops; no pause, no freezing, no twitching, no dancing. "
T={}
T['kitsune_ti_idle']=(False,"Idle. She is alive the whole time with slow continuous motion: she slowly shifts her whole weight onto one leg so that her hips and shoulders tilt, then slowly onto the other leg; her torso leans and sways, her knees bend softly, she fans herself slowly with the folding fan close to her face, her head tilts left and then right, her fox ears twitch, her hair drifts, and all nine tails wave slowly up and down behind her without spreading wider. "+IDLE_END)
T['athena_bt_idle']=(False,"Idle. She is alive the whole time with slow continuous motion: she slowly shifts her whole weight onto one leg so that her hips and shoulders tilt, then slowly onto the other leg; her torso leans and sways, her knees bend softly, she slowly turns her head in the helmet left and then right, rolls her shoulders, lowers the shield a hand's width and brings it back; her red cloak and the helmet crest sway. The spear stays upright the whole time, never tilts, swings or is raised. "+IDLE_END)
T['demeter_bt_idle']=(False,"Idle. She is alive the whole time with slow continuous motion: she slowly shifts her whole weight onto one leg so that her hips and shoulders tilt, then slowly onto the other leg; her torso leans and sways, she slowly turns her head left and then right, lifts and settles the sheaf of wheat on her arm, the hand with the sickle drifts a little forward and back; her cloak, dress and hair sway. The sickle is never raised. "+IDLE_END)
T['kitsune_ti_atk']=(True,"Basic attack. The fan stays exactly where it is beside her head the whole time and the arm does not move away from the body; only her wrist tilts the fan a little; the fan never sweeps and never reaches the edges of the frame. Within the first third of a second rich blue fox-fire flares along the top edge of the fan and one blue flame leaps from the fan straight up and leaves through the top edge of the frame. Her hips and tails sway a little. Then the flame on the fan fades during a long relaxed recovery and she returns to the starting pose. ")
T['athena_bt_atk']=(True,"Basic attack. The spear stays vertical the whole time, it never tilts and never points sideways or at the corners; the shield stays at her side. Within the first third of a second she bends her knees a little and then thrusts the vertical spear straight up, so that its tip, glowing rich gold, rises above her helmet, and a short golden streak leaves the tip straight up through the top edge of the frame. Then the glow fades during a long relaxed recovery and she lowers the spear back to the starting pose. ")
AIM="like shooting at a bird directly above her: the arrow points almost vertically at the top edge of the frame, never horizontally and never at a corner; "
END_A="Only the bow and the arrows glow; her body keeps its natural colours. The bow stays close to her body. "
for s in ('bt','ti'):
    T[f'artemis_{s}_atk']=(True,"Basic attack. Within the first third of a second she leans back, looks up at the sky and aims the bow high overhead "+AIM+"she draws the string down to her chin with an arrow of pale silver-blue moonlight and releases: the string snaps and the arrow flies up and leaves through the middle of the top edge of the frame. "+END_A+"Then the glow on the bow fades during a long relaxed recovery and she lowers the bow to the starting pose. ")
    T[f'artemis_{s}_sup']=(True,"Super skill Moon Volley. Within the first second she plants her feet, leans back, looks up at the sky and aims the bow high overhead "+AIM+"silver-blue moonlight runs along the bow limbs and the string, she draws the string down to her chin with three arrows of moonlight held close together and releases: the string snaps and the three arrows fly up side by side and leave through the middle of the top edge of the frame. "+END_A+"Then the moonlight on the bow fades and she lowers the bow to the starting pose. ")
    T[f'artemis_{s}_hyp']=(False,"Ultimate skill Hunt of the Giant. Within the first second she drops to one knee on the same spot, leans back, looks up at the sky and aims the bow high overhead "+AIM+"she slowly draws the string down to her chin with one long thick arrow of bright silver-blue moonlight, no threads or lines of light in the air, and releases: the string snaps and the heavy arrow flies up and leaves through the middle of the top edge of the frame. "+END_A+"Then the moonlight fades, she stands up and lowers the bow to the starting pose. ")
Z="Ultimate skill Lightning of the Titan War. The staff stays upright the whole time, never tilts, swings or lies horizontally. Within the first second he raises his free fist to the height of his head with a bent elbow, and a compact knot of rich blue-white lightning crackles around the fist only. Then he punches the fist straight up above his head and one thick lightning bolt shoots from the fist straight up and leaves through the top edge of the frame for half a second, while small sparks run up the staff. The lightning touches only the fist and the staff: his face, skin, hair, armour and robes keep their normal colours the whole time and are never covered by light, glow or lightning; no rays around the body, no column of light over the body. Then the lightning fades and he returns to the starting pose. "
T['zeus_bt_hyp']=(True,Z); T['zeus_ti_hyp']=(True,Z)
P={}
for c,(planted,tl) in T.items():
    key='_'.join(c.split('_')[:2]); desc,pron,col=D[key]
    P[c]=HEAD+body(desc,pron,planted)+tl+tail(col, c.endswith('_idle'))
